SELECT "YaleLanguages_3"."Calculation_3110108110633423" AS "Calculation_3110108110633423",   SUM(CAST("YaleLanguages_3"."Number_of_Records" AS BIGINT)) AS "sum_Number_of_Records_ok",   CAST(EXTRACT(YEAR FROM "YaleLanguages_3"."CHARGE_DATE") AS BIGINT) AS "yr_CHARGE_DATE_ok" FROM "YaleLanguages_3" WHERE ((CAST("YaleLanguages_3"."CHARGE_DATE" as DATE) >= cast('2002-01-01' as DATE)) AND ("YaleLanguages_3"."PATRON_TYPE__Pseudo_vs_Patron_" = 'Patron')) GROUP BY "Calculation_3110108110633423",   "yr_CHARGE_DATE_ok";
